export const DISABLABLE_TAGS=["button","fieldset","optgroup","option","select","textarea","input"];export const FOCUSABLE_TAGS=["button","input","select","textarea","a[href]","audio[controls]","video[controls]",'[tabindex="0"]','[contenteditable="true"]'];export const FOCUSABLE_SELECTOR=FOCUSABLE_TAGS.map((t=>DISABLABLE_TAGS.includes(t)?`${t}:not(:disabled)`:t)).map((t=>`${t}:not([tabindex="-1"])`)).join(",");export function isFocusable(t){return isFocusableIfNotInert(t)&&!isInert(t)}export function isFocusableIfNotInert(t){return t.matches(FOCUSABLE_SELECTOR)&&isVisibilityVisible(t)}export function isVisibilityVisible(t){return"visible"===getComputedStyle(t).visibility}export function isInert(t,e){if(t.matches("[inert],[inert] *"))return!0;let i=t;for(;i!==e&&null!==i;){if(isDisplayNone(i))return!0;i=i.parentElement}return!1}export function isInertRoot(t){return t.matches("[inert]")||isDisplayNone(t)}export function isDisplayNone(t){return"none"===getComputedStyle(t).display}export function getActiveElementSelectors(){return FOCUSABLE_SELECTOR}export function createScopedVisibleElementFilter(t){return e=>isVisibilityVisible(e)&&!isInert(e,t)}export function isHTMLOrSVGElement(t){return t instanceof HTMLElement||t instanceof SVGElement}